// docs/platforms.md is generated by tool/platform_matrix.dart. This fails when
// a descriptor changed and nobody regenerated the page, or when someone edited
// the page by hand (the edit belongs in the generator).

import 'dart:io';

import 'package:neforum_core/neforum_core.dart';
import 'package:test/test.dart';

import '../tool/platform_matrix.dart';

void main() {
  test('docs/platforms.md is the output of tool/platform_matrix.dart', () {
    final file = File(platformsDocPath);
    expect(file.existsSync(), isTrue, reason: 'run from packages/neforum_core');
    final committed = file.readAsStringSync().replaceAll('\r\n', '\n');
    final date = platformMatrixDate(committed);
    expect(date, isNotNull, reason: 'the page lost its "Generated from the code on" line');
    expect(committed, renderPlatformMatrix(builtinRegistry(), date!),
        reason: 'docs/platforms.md is stale: in packages/neforum_core run '
            '`dart run tool/platform_matrix.dart --write`, then `dart run tool/sync_docs.dart` in apps/neforum_app');
  });

  test('the Media paragraph names the networks that thread their media', () {
    final page = renderPlatformMatrix(builtinRegistry(), '2000-01-01');
    final paragraph = page.split('\n').firstWhere((l) => l.startsWith('The **Media** column'));
    for (final d in builtinRegistry().descriptors) {
      final threads = d.text.supportsThreads && d.media.mediaPerThreadPart;
      expect(paragraph.contains(d.name), threads, reason: d.name);
    }
  });
}
